/*
 * SAVE ONE OF THE LEARNER'S ANSWERS TO THEIR PROJECT — ONLY IF NOBODY ELSE HAS
 * CHANGED IT SINCE IT WAS READ (TASK-L177; OpenNoodl HLT-016 AC6).
 *
 * The product's `captureProjectFact`, on compare-and-swap instead of a row lock.
 * The product's L62: two captures both read version n, both wrote n+1, and the
 * second write replaced the first's whole `facts` map while both callers were
 * told it had worked. Here the write carries `ifMatch: { version: n }`, so the
 * backend applies it only if the row still holds n, in the same UPDATE; the
 * loser gets `precondition-failed`, reads again and merges onto what is there.
 *
 * IDENTITY COMES FROM THE SESSION (`Caller learner`), never from an argument. A
 * write that took a learner id is a write somebody can aim at somebody else.
 *
 * THE FIELD MUST BE ONE THEY CAN ACTUALLY BE ASKED FOR: a `capture` section, or
 * an `activity` that captures a fact, on their lesson for a live, unlocked step
 * of their newest path (the `lesson` function's gate, ported). The product's
 * route checks only the length, and sprint 31 recorded a typo'd namespace
 * landing in `facts` forever; this function's one legitimate caller is a section
 * on a lesson, so it has the list.
 *
 * A CONFLICT IS NEVER A 200 (L62: a swallowed conflict is worse than none). It is
 * re-read and retried, at most 8 times; after that the caller is refused and the
 * page says it could not save. A retry logs the learner id and the attempt —
 * never what they wrote.
 *
 * Every refusal is one body (the mcp/auth.ts rule): "not yours", "not there" and
 * "not askable" cannot be told apart.
 */
/*
 * NOT UNDER AN OUT-OF-DATE PRIVACY NOTICE (TASK-L185 §2). `noticeCurrent` is
 * shared/Notice's answer for this session's account. A stale one is refused
 * with its own body, so the page can tell "accept the notice first" from
 * "could not be saved". Reads are not gated here, as in the product: the gate
 * in App decides what the browser draws; the server refuses the WRITE.
 */
if (Inputs.learnerId !== undefined && Inputs.conceptId !== undefined && Inputs.field !== undefined && Inputs.value !== undefined && Inputs.noticeCurrent !== undefined) {
  (async () => {
    const refuse = (why) => {
      Outputs.error = why;
      console.error('[dbt:capture] refused: ' + why + ' learner=' + String(Inputs.learnerId || '-'));
      Outputs.failed();
    };
    if (Inputs.noticeCurrent !== true) {
      console.warn('[dbt:capture] refused: notice not accepted learner=' + String(Inputs.learnerId || '-'));
      Outputs.stale();
      return;
    }
    try {
      const q = (c, where, limit) => Noodl.Records.query(c, where, { limit: limit || 1000, plain: true });
      const learnerId = String(Inputs.learnerId || '');
      const conceptId = String(Inputs.conceptId || '');
      const field = String(Inputs.field || '');
      const value = String(Inputs.value === null ? '' : Inputs.value).trim();
      // The product's route: field 1–128, value 1–2000 (after the trim its client does).
      if (!learnerId) return refuse('no learner');
      if (!conceptId) return refuse('no concept');
      if (field.length < 1 || field.length > 128) return refuse('field length');
      if (value.length < 1 || value.length > 2000) return refuse('value length');

      // ── The gate: a live, unlocked step on their newest path, whose lesson asks for this field.
      const [paths, lessons] = await Promise.all([
        q('LearningPath', { learnerId: { equalTo: learnerId } }),
        q('Lesson', { and: [{ learnerId: { equalTo: learnerId } }, { conceptId: { equalTo: conceptId } }] })
      ]);
      const live = [...paths].sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))[0];
      if (!live) return refuse('no path');
      const steps = await q('PathStep', { and: [{ pathId: { equalTo: live.pathId } }, { conceptId: { equalTo: conceptId } }] });
      const step = steps.find((s) => (s.removedAt === undefined || s.removedAt === null) && s.status !== 'locked');
      if (!step) return refuse('step not open');
      const lesson = [...lessons].sort((a, b) => (b.generationVersion ?? 0) - (a.generationVersion ?? 0))[0];
      if (!lesson) return refuse('no lesson');
      const askable = (lesson.sections || []).some((s) =>
        (s.kind === 'capture' && s.field === field) ||
        (s.kind === 'activity' && s.capturesProjectFact && s.capturesProjectFact.field === field));
      if (!askable) return refuse('field not asked');

      // ── Read, merge ONE field, write only if unchanged; on a conflict, again.
      const MAX_ATTEMPTS = 8;
      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
        const contexts = await q('ProjectContext', { learnerId: { equalTo: learnerId } }, 2);
        if (contexts.length !== 1) return refuse(contexts.length ? 'two contexts' : 'no context');
        const ctx = contexts[0];
        const version = Number(ctx.version);
        const facts = ctx.facts && typeof ctx.facts === 'object' ? ctx.facts : {};
        // Identical words are a no-op: nothing written, the version does not move.
        if (facts[field] === value) {
          Outputs.version = version;
          Outputs.bumped = false;
          Outputs.done();
          return;
        }
        const next = Object.assign({}, facts);
        next[field] = value;
        try {
          await Noodl.Records.save(ctx.objectId, { facts: next, version: version + 1 }, { className: 'ProjectContext', ifMatch: { version } });
          Outputs.version = version + 1;
          Outputs.bumped = true;
          Outputs.done();
          return;
        } catch (e) {
          if (!e || e.code !== 'precondition-failed') throw e;
          // Somebody else wrote their project since it was read. Read it again.
          console.warn('[dbt:capture] conflict learner=' + learnerId + ' attempt=' + attempt);
          await new Promise((r) => setTimeout(r, 5 + Math.floor(Math.random() * 25)));
        }
      }
      return refuse('still conflicting after ' + MAX_ATTEMPTS + ' attempts');
    } catch (e) {
      refuse(String((e && e.message) || e));
    }
  })();
}
